# Batch 10 - add webmail compose routes to the relay-free inquiry panel.
# A buyer whose browser has no desktop mail client (very common) can now finish
# the inquiry in Gmail or Outlook web compose with every field prefilled, instead
# of being told to copy and paste.
import base64
import pathlib
import re
import sys

NEW_JS = base64.b64decode(
    ""
).decode("utf-8")

ROOT = pathlib.Path('.')


def read(p):
    return p.read_text(encoding='utf-8', errors='replace')


def main():
    js_path = ROOT / 'assets' / 'inquiry-form.js'
    before = read(js_path) if js_path.exists() else ''
    if before != NEW_JS:
        js_path.write_text(NEW_JS, encoding='utf-8')
        print('inquiry-form.js: written (%d bytes)' % len(NEW_JS.encode('utf-8')))
    else:
        print('inquiry-form.js: unchanged')

    bumped = 0
    for p in sorted(ROOT.rglob('*.html')):
        s = read(p)
        if 'inquiry-form.js?v=3' in s:
            p.write_text(s.replace('inquiry-form.js?v=3', 'inquiry-form.js?v=4'), encoding='utf-8')
            bumped += 1
    print('cache-bust bumped to v4: %d pages' % bumped)

    stale = [str(p.relative_to(ROOT)) for p in sorted(ROOT.rglob('*.html'))
             if re.search(r'inquiry-form\.js\?v=(?:1|2|3)(?!\d)', read(p))]
    if stale:
        sys.exit('pages still on an old version: %s' % ', '.join(stale[:10]))
    print('pages on an old version: 0')

    left = [str(p) for p in sorted(ROOT.rglob('*'))
            if p.is_file() and p.suffix in ('.html', '.js', '.json', '.xml')
            and 'formsubmit' in read(p).lower()]
    if left:
        sys.exit('formsubmit still referenced in: %s' % ', '.join(left))
    print('relay references remaining: 0')

    live = read(ROOT / 'assets' / 'inquiry-form.js')
    for marker in ('mail.google.com', 'outlook.office.com', 'wa.me/8615339005193', 'data-wa-intake'):
        if marker not in live:
            sys.exit('inquiry-form.js missing marker: %s' % marker)
    print('web compose routes present: gmail, outlook')

    sm = ROOT / 'sitemap.xml'
    if sm.exists():
        print('sitemap locs: %d' % len(re.findall(r'<loc>', read(sm))))
    print('DONE')


if __name__ == '__main__':
    main()
